() => {
  const candidates = document.querySelectorAll('[role="tooltip"], [data-tooltip], [class*="tooltip" i], [class*="Tooltip"]');
  const results = [];
  candidates.forEach(el => {
    const r = el.getBoundingClientRect();
    const style = getComputedStyle(el);
    results.push({
      text: (el.textContent || '').trim().slice(0, 120),
      tag: el.tagName,
      className: String(el.className).slice(0, 100),
      visible: r.width > 0 && r.height > 0 && style.visibility !== 'hidden' && style.opacity !== '0',
      rect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
      opacity: style.opacity,
      transitionDelay: style.transitionDelay,
      transitionDuration: style.transitionDuration
    });
  });
  return results;
}

() => {
  const btns = [...document.querySelectorAll('button')].filter(b => b.getAttribute('aria-label') === '配置问数范围');
  if (!btns.length) return 'no button found';
  const b = btns[0];
  const info = {
    title: b.title || null,
    ariaLabel: b.getAttribute('aria-label'),
    className: b.className,
    outerHTMLStart: b.outerHTML.slice(0, 400)
  };
  // 看看它父级附近有没有 hint/bubble 相关元素
  const card = b.closest('div');
  const nearby = b.parentElement ? b.parentElement.outerHTML.slice(0, 600) : '';
  return { info, nearby };
}

() => {
  const btn = [...document.querySelectorAll('button')].filter(b => b.getAttribute('aria-label') === '配置问数范围')[0];
  const wrapper = btn.closest('.group\\/tip');
  if (!wrapper) return 'wrapper not found';
  const tip = wrapper.querySelector(':scope > *:not(button)');
  if (!tip) return { wrapperHTML: wrapper.outerHTML.slice(0, 1200) };
  const r = tip.getBoundingClientRect();
  const style = getComputedStyle(tip);
  return {
    tipHTML: tip.outerHTML.slice(0, 500),
    text: (tip.textContent || '').trim(),
    visible: r.width > 0 && r.height > 0,
    opacity: style.opacity,
    rect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
    viewport: { w: window.innerWidth, h: window.innerHeight },
    overflowRight: r.x + r.width > window.innerWidth,
    overflowBottom: r.y + r.height > window.innerHeight,
    transitionDelay: style.transitionDelay,
    transitionDuration: style.transitionDuration
  };
}

() => {
  const btn = [...document.querySelectorAll('button')].filter(b => b.getAttribute('aria-label') === '配置问数范围')[0];
  const wrapper = btn.closest('.group\\/tip');
  const tip = wrapper.querySelector(':scope > span');
  const style = getComputedStyle(tip);
  return {
    wrapperIsHovered: wrapper.matches(':hover'),
    btnIsHovered: btn.matches(':hover'),
    tipOpacity: style.opacity,
    tipVisible: tip.getBoundingClientRect().height > 0
  };
}

() => {
  const btn = [...document.querySelectorAll('button')].filter(b => b.getAttribute('aria-label') === '配置问数范围')[0];
  const wrapper = btn.closest('.group\\/tip');
  const tip = wrapper.querySelector(':scope > span');
  tip.style.opacity = '1';
  const r = tip.getBoundingClientRect();
  return {
    text: tip.textContent.trim(),
    rect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
    rightEdge: Math.round(r.x + r.width),
    viewportW: window.innerWidth,
    overflowRight: r.x + r.width > window.innerWidth,
    overflowBottom: r.y + r.height > window.innerHeight
  };
}

() => {
  // 验证真实 hover 状态下删除按钮气泡
  const btn = [...document.querySelectorAll('button')].filter(b => b.getAttribute('aria-label') === '删除数据源')[0];
  const wrapper = btn.closest('.group\\/tip');
  const tip = wrapper.querySelector(':scope > span');
  const check = {
    hovered: wrapper.matches(':hover'),
    opacityWhileHover: getComputedStyle(tip).opacity,
    text: tip.textContent.trim()
  };
  // 恢复第一个 tip 的 inline style，冻结当前 hover 显示用于截图
  const firstTip = [...document.querySelectorAll('button')].filter(b => b.getAttribute('aria-label') === '配置问数范围')[0]
    .closest('.group\\/tip').querySelector(':scope > span');
  firstTip.style.opacity = '';
  tip.style.opacity = '1';
  const r = tip.getBoundingClientRect();
  check.rect = { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
  check.rightEdge = Math.round(r.x + r.width);
  check.viewportW = window.innerWidth;
  check.overflowRight = r.x + r.width > window.innerWidth;
  check.overflowBottom = r.y + r.height > window.innerHeight;
  check.transitionDelay = getComputedStyle(tip).transitionDelay;
  return check;
}

() => {
  // 「客户拜访管理」卡片的 切换数据自省开关 按钮（第4张卡片，MySQL 类型）
  const btns = [...document.querySelectorAll('button')].filter(b => b.getAttribute('aria-label') === '切换数据自省开关');
  const btn = btns[1]; // 0=PostgreSQL 卡片, 1=客户拜访管理卡片
  const wrapper = btn.closest('.group\\/tip');
  const tip = wrapper.querySelector(':scope > span');
  const check = {
    hovered: wrapper.matches(':hover'),
    opacityWhileHover: getComputedStyle(tip).opacity,
    text: tip.textContent.trim(),
    transitionDelay: getComputedStyle(tip).transitionDelay
  };
  // 恢复删除按钮 tip 的 inline style，冻结当前显示
  const delTip = [...document.querySelectorAll('button')].filter(b => b.getAttribute('aria-label') === '删除数据源')[0]
    .closest('.group\\/tip').querySelector(':scope > span');
  delTip.style.opacity = '';
  tip.style.opacity = '1';
  const r = tip.getBoundingClientRect();
  check.rect = { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
  check.rightEdge = Math.round(r.x + r.width);
  check.viewportW = window.innerWidth;
  check.overflowRight = r.x + r.width > window.innerWidth;
  check.overflowBottom = r.y + r.height > window.innerHeight;
  return check;
}

() => {
  // 滚动该按钮所在卡片至视口中部，模拟用户滚动后悬停的真实场景
  const btns = [...document.querySelectorAll('button')].filter(b => b.getAttribute('aria-label') === '切换数据自省开关');
  const btn = btns[1];
  const card = btn.closest('.group\\/tip');
  card.scrollIntoView({ block: 'center' });
  const tip = card.querySelector(':scope > span');
  const r = tip.getBoundingClientRect();
  return {
    tipRect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
    bottomEdge: Math.round(r.y + r.height),
    rightEdge: Math.round(r.x + r.width),
    viewportW: window.innerWidth,
    viewportH: window.innerHeight,
    overflowRight: r.x + r.width > window.innerWidth,
    overflowBottom: r.y + r.height > window.innerHeight
  };
}

() => {
  document.querySelectorAll('.group\\/tip > span[style]').forEach(el => { el.style.opacity = ''; });
  const remaining = document.querySelectorAll('.group\\/tip > span[style]').length;
  return { cleaned: remaining === 0 };
}

() => {
  // 移除所有 tip span 上的 style 属性
  document.querySelectorAll('span.pointer-events-none').forEach(el => {
    if (el.closest('.group\\/tip')) el.removeAttribute('style');
  });
  const left = [...document.querySelectorAll('.group\\/tip > span')].filter(el => el.hasAttribute('style')).length;
  return { remainingWithStyle: left };
}
